"""THE REGISTRY OF PROVENANCE (Kaveh 2026-10-12: "keep track of the handwritten lemmas separate from the auto-generated
lemmas so that we can reason about them ... keep track of the base vocabulary separate from everything else").

  BASE        base_vocabulary.py <-> Lean Ideas.Base.Vocabulary <-> Rust vocab.rs (chosen with Kaveh; never generated)
  HANDWRITTEN HANDWRITTEN below (measure components written by people, in Rust mating.rs) and every Lean file outside
              Ideas/Base and Ideas/Generated
  GENERATED   generated_registry.json (this directory): each entry a term over the base with its hole and its evidence;
              `export()` writes Lean Ideas/Generated/Measures.lean and Rust src/generated.rs from it -- never edit those

  python -m catspace.incubator.analyst.discovery.registry --summary | --export
"""
from __future__ import annotations

import argparse
import datetime
import json
from pathlib import Path

from . import base_vocabulary as V

HERE = Path(__file__).resolve().parent
REPO = HERE.parents[3]
REGISTRY = HERE / "generated_registry.json"
LEAN_OUT = REPO / "lean/ideas/Ideas/Generated/Measures.lean"
RUST_OUT = REPO / "rust/analyst_core/src/generated.rs"

# the hand-written measure components the frames use (rust/analyst_core/src/mating.rs)
HANDWRITTEN = [
    dict(id="wall", frame="KR", rust="mating::wall_rows", gloss="rows beyond the rook's wall", origin="the discoverer's regression, coded by hand"),
    dict(id="opposition", frame="KR", rust="mating::kr_opposition", gloss="our king's distance to the opposition square", origin="the discoverer's regression, coded by hand"),
    dict(id="chase", frame="KR", rust="mating::kr_chase", gloss="opposition distance plus the lone king's room away from our king", origin="by hand from the certificate's gaps (2026-10-12)"),
    dict(id="kq_offedge", frame="KQ", rust="mating::off_edge", gloss="region squares off the edge", origin="from Lean kq_mate_on_edge"),
    dict(id="kq_approach", frame="KQ", rust="mating::approach", gloss="our king's distance to the farthest front-zone target", origin="from Lean edge_shape / corner_shape"),
    dict(id="kq_region", frame="KQ", rust="mating::region_size", gloss="the lone king's region size", origin="by hand"),
]


def load() -> list:
    return json.loads(REGISTRY.read_text()) if REGISTRY.exists() else []


def save(entries: list) -> None:
    REGISTRY.write_text(json.dumps(entries, indent=1) + "\n")


def add_generated(id: str, expr: str, kind: str, hole: str, evidence: dict, used_by: str = "", piece_name: str = "our other piece") -> dict:
    """Record a term the pipeline found (replacing an entry of the same id)."""
    t = V.parse(expr)
    e = dict(id=id, provenance="generated", kind=kind, expr=V.sexpr(t), gloss=V.gloss(t, piece_name), size=V.size(t),
             lean=V.lean(t), hole=hole, evidence=evidence, used_by=used_by, created=datetime.date.today().isoformat())
    entries = [x for x in load() if x["id"] != id] + [e]
    save(entries)
    return e


def export() -> None:
    """Write the generated track's Lean module and Rust constants from the registry."""
    entries = load()
    lean = ["import Ideas.Base.Vocabulary", "",
            "/-! AUTO-GENERATED by catspace/incubator/analyst/discovery/registry.py from generated_registry.json -- do not edit",
            "by hand. THE GENERATED TRACK (Kaveh 2026-10-12): terms over the base vocabulary (Ideas.Base.Vocabulary) the",
            "discovery pipeline found, each with its hole and its verifier evidence. Parameters: the position `p`, our colour",
            "`c`, our king `W`, their king `L`, our other piece `P`. -/", "",
            "set_option linter.unusedVariables false", "", "namespace Ideas.Generated", "", "open Chess Ideas.Vocabulary", ""]
    rust = ["//! AUTO-GENERATED by catspace/incubator/analyst/discovery/registry.py from generated_registry.json -- do not edit by",
            "//! hand. THE GENERATED TRACK (Kaveh 2026-10-12): terms over the base vocabulary (vocab.rs) the discovery pipeline",
            "//! found, with their evidence; the frames read them from here.", ""]
    for e in entries:
        ev = "; ".join(f"{k}: {v}" for k, v in e["evidence"].items())
        lean += [f"/-- {e['id']}: {e['gloss']}. ({e['created']}, hole {e['hole']}; {ev}) -/",
                 f"def {e['id']} (p : Position) (c : Color) (W L P : Square) : Nat := {e['lean']}", ""]
        rust += [f"/// {e['id']}: {e['gloss']} ({e['created']}, hole {e['hole']}; {ev}; used by {e['used_by'] or '-'})",
                 f"pub const {e['id'].upper()}: &str = \"{e['expr']}\";", ""]
    lean += ["end Ideas.Generated", ""]
    LEAN_OUT.parent.mkdir(parents=True, exist_ok=True)
    LEAN_OUT.write_text("\n".join(lean))
    RUST_OUT.write_text("\n".join(rust))
    print(f"OBS exported {len(entries)} generated entries -> {LEAN_OUT.relative_to(REPO)}, {RUST_OUT.relative_to(REPO)}")


def summary() -> None:
    """The three tracks side by side."""
    lean_dir = REPO / "lean/ideas/Ideas"
    files = sorted(lean_dir.rglob("*.lean"))
    count = lambda fs: sum(f.read_text().count("\ntheorem ") + f.read_text().count("\nlemma ") for f in fs)
    base = [f for f in files if "Base" in f.parts]
    gen = [f for f in files if "Generated" in f.parts]
    hand = [f for f in files if f not in base and f not in gen]
    print(f"OBS BASE: {len(V.PRIMITIVES)} primitives (base_vocabulary.py / Ideas.Base.Vocabulary / vocab.rs)")
    print(f"OBS HANDWRITTEN: {count(hand)} Lean theorems in {len(hand)} files; {len(HANDWRITTEN)} measure components in mating.rs")
    print(f"OBS GENERATED: {len(load())} terms in the registry ({count(gen)} Lean theorems so far)")
    for e in load():
        print(f"OBS   {e['id']} = {e['expr']} -- {e['gloss']} [{e['hole']}] {e['evidence']}")


def main(argv=None):
    ap = argparse.ArgumentParser()
    ap.add_argument("--export", action="store_true")
    ap.add_argument("--summary", action="store_true")
    a = ap.parse_args(argv)
    if a.export:
        export()
    if a.summary or not a.export:
        summary()


if __name__ == "__main__":
    main()
